function renderWardrobe(){const grid=$('#skinCards');grid.replaceChildren();for(const [i,id] of ['neo','skin-garden','skin-night'].entries()){const b=document.createElement('button');b.className='skin-card';b.setAttribute('aria-pressed',String(art.skin===id));const portrait=document.createElement('canvas');portrait.id='skinPortrait'+i;portrait.width=256;portrait.height=280;b.append(portrait);const label=document.createElement('strong');label.textContent=['COURIER','GARDEN EXPLORER','NIGHT COURIER'][i];b.append(label);const note=document.createElement('span');note.textContent=art.skin===id?'◆ ĐANG MẶC':'CHỌN TRANG PHỤC';b.append(note);b.onclick=()=>{$('#homeSkin').value=id;art.skin=id;$('#skin').value=id;saveCampaignChoice(campaignChoice.level);renderWardrobe();menuRasterTime=-1};grid.append(b)}}
function menuKey(e){if(e.code==='Tab'){trapMenuFocus(e,$('#campaignHome'));return}if(e.code==='Escape'){e.preventDefault();if(menuScreen!=='home')menuSetScreen('home');else if(!$('#closeCampaign').hidden)hideCampaign()}}
function trapMenuFocus(e,root){const list=Array.from(root.querySelectorAll?.('button:not([hidden]),select:not([hidden])')||[]).filter(b=>b.offsetParent!==null);if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function showPauseMenu(){if(narrative.active||globalThis.neonMenuOpen||won)return;pause(true);$('#pauseOverlay').hidden=false;$('#pauseDestination').textContent=L.id+' · '+L.name;$('#pauseMission').textContent=L.objective;$('#pauseStats').textContent='● '+L.coins.filter(c=>c.taken).length+' · '+Math.round(elapsed)+'s · '+deaths+' lần hồi sinh';$('#pauseResume').focus?.()}
function closePauseMenu(){ $('#pauseOverlay').hidden=true;pause(false);$('#pause').focus?.() }
function drawMenuPresentation(){
 if(!globalThis.neonMenuOpen||!art.ready||(experience.reduced&&menuRasterTime>=0))return;const now=globalThis.performance?.now?.()||Date.now();if(menuRasterTime>=0&&now-menuRasterTime<67)return;menuRasterTime=now;
 const frame=experience.reduced?0:Math.floor(now/145)%ANIM_META.idle.frames.length;
 function actor(g,id,x,y,size,flip=false){g.save();g.translate(x,y);g.scale(flip?-1:1,1);g.drawImage(HERO_SHEETS[id],frame*128,0,128,128,-size/2,-size*104/128,size,size);g.restore()}
 if(menuScreen==='home'){const g=$('#menuHero').getContext('2d');g.clearRect(0,0,520,500);g.imageSmoothingEnabled=false;g.fillStyle='#071b2744';g.beginPath();g.ellipse(270,442,170,24,0,0,Math.PI*2);g.fill();actor(g,art.skin,265,442,470);const pip=ART_IMAGES.pip;g.drawImage(pip,362,350,100,100)}
 if(menuScreen==='wardrobe')for(const [i,id] of ['neo','skin-garden','skin-night'].entries()){const g=$('#skinPortrait'+i).getContext('2d');g.clearRect(0,0,256,280);g.imageSmoothingEnabled=false;actor(g,id,128,263,300)}
}
function initCampaign(){
 $('#pauseOverlay').hidden=true;
 try{const saved=JSON.parse(localStorage.getItem('neon-run-campaign-choice')||'{}');if(Number.isInteger(saved.level)&&saved.level>=0&&saved.level<40)campaignChoice.level=saved.level;if(['neo','skin-garden','skin-night'].includes(saved.skin))campaignChoice.skin=saved.skin}catch{}
 art.skin=campaignChoice.skin;$('#skin').value=art.skin;$('#campaignHome').style.setProperty('--home-art','url('+ART_IMAGES['bg-world1'].src+')');
 $('#continueCampaign').onclick=()=>playCampaign(campaignChoice.level);$('#closeCampaign').onclick=hideCampaign;$('#levelsMenu').onclick=()=>openCampaign(false,'journey');$('#launchStage').onclick=()=>playCampaign(menuStage);
 $('#homeSkin').onchange=()=>{art.skin=$('#homeSkin').value;$('#skin').value=art.skin;saveCampaignChoice(campaignChoice.level)};
 for(const [id,name] of [['navHome','home'],['navJourney','journey'],['navWardrobe','wardrobe'],['navSettings','settings']])$('#'+id).onclick=()=>menuSetScreen(name);
 $('#navJournal').onclick=openJournal;$('#menuFx').onclick=()=>{$('#lowFx').onclick();$('#menuFx').textContent=experience.reduced?'✦ Hiệu ứng: nhẹ':'✦ Hiệu ứng: đầy đủ'};$('#menuFull').onclick=()=>$('#full').onclick();
 $('#pause').onclick=showPauseMenu;$('#restart').hidden=true;$('#pauseResume').onclick=closePauseMenu;$('#pauseRetry').onclick=()=>playCampaign(idx);$('#pauseMap').onclick=()=>{closePauseMenu();openCampaign(false,'journey')};$('#pauseHome').onclick=()=>{closePauseMenu();openCampaign(false,'home')};
 $('#pauseOverlay').addEventListener('keydown',e=>{if(e.code==='Tab')trapMenuFocus(e,$('#pauseOverlay'));if(e.code==='Escape'){e.preventDefault();e.stopPropagation();closePauseMenu()}});
 if(!globalThis.__NEON_QA_NO_AUTOSTORY__)openCampaign(true);
}

