const ENCOUNTER_IMAGES={};
const experience={reduced:!!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches,props:true};
function encounterBlit(world,clip,index,x,y,w,h,flip=false){
 const im=ENCOUNTER_IMAGES[world],r=ENCOUNTER_META.worlds[world].clips[clip][Math.max(0,Math.min(3,index))];
 if(!im||x+w<cam||x>cam+W)return;
 ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(Math.round(x+(flip?w:0)),Math.round(y));if(flip)ctx.scale(-1,1);ctx.drawImage(im,...r,0,0,Math.round(w),Math.round(h));ctx.restore();
}
function drawEncounterProps(){
 if(!experience.props||L.rooms)return;
 const candidates=L.boss?[L.boss.arena[0]+30,L.boss.arena[1]-60]:[L.spawn[0]+160,L.cp-110,L.exit-165];
 for(let i=0;i<candidates.length;i++){
  const x=candidates[i];if(L.objects.some(o=>Math.abs(o.x-x)<75))continue;
  const floor=L.platforms.find(s=>s.y===350&&s.x<=x-24&&s.x+s.w>=x+24);if(!floor)continue;
  const size=56;encounterBlit(L.world,'props',i,x-size/2,floor.y-size*116/128,size,size);
 }
}
function encounterPhaseFrame(b){const duration=b.phase==='tell'?1.05:b.phase==='recover'?BOSS_COMBAT.recovery:b.style===3?1.1:.75;return experience.reduced?1:Math.min(3,Math.max(0,Math.floor((1-b.timer/duration)*4)))}
function drawEncounterTelegraph(){
 const b=L.boss;if(!b||b.dead||b.phase!=='tell')return;
 const frame=encounterPhaseFrame(b),center=b.x+b.w/2;
 encounterBlit(L.world,'tell',frame,center-36,b.y-112,72,72);
 ctx.save();ctx.strokeStyle='#ffdc8d';ctx.fillStyle='#241c32';ctx.lineWidth=2;
 if(b.style===4){
  // This marker is the existing falling projectile footprint, not a new damage event.
  ctx.strokeStyle='#171a30';ctx.lineWidth=5;ctx.strokeRect(b.targetX,315,30,35);ctx.strokeStyle='#ffdc8d';ctx.lineWidth=2;ctx.strokeRect(b.targetX,315,30,35);encounterBlit(4,'tell',frame,b.targetX-9,326,48,48);
 }else if([1,3,5].includes(b.style)){
  const speed=b.style===3?360:260,duration=b.style===3?1.1:.75;
  const end=Math.max(b.arena[0],Math.min(b.arena[1],center+b.direction*speed*duration));
  ctx.beginPath();ctx.moveTo(center,343);ctx.lineTo(end,343);ctx.stroke();
  ctx.beginPath();ctx.moveTo(end,343);ctx.lineTo(end-b.direction*12,337);ctx.lineTo(end-b.direction*12,349);ctx.closePath();ctx.fillStyle='#ffdc8d';ctx.fill();
 }
 if([2,5].includes(b.style)){ctx.fillStyle='#ffdc8d';ctx.font='bold 18px system-ui';ctx.fillText('←  →',center-25,323)}
 ctx.restore();
}
function drawEncounterProjectile(q){
 const im=ENCOUNTER_IMAGES[L.world],frame=experience.reduced?1:Math.floor(clock*10)%3,r=ENCOUNTER_META.worlds[L.world].clips.attack[frame];
 if(!im)return;
 // Crop the registered center so a projectile fills its gameplay-owned bounds.
 ctx.save();ctx.translate(Math.round(q.x+(q.vx<0?q.w:0)),Math.round(q.y));if(q.vx<0)ctx.scale(-1,1);
 ctx.drawImage(im,r[0]+32,r[1]+32,64,64,0,0,q.w,q.h);ctx.strokeStyle='#ffe5c3';ctx.lineWidth=1;for(const [x,y,sx,sy] of [[0,0,1,1],[q.w,0,-1,1],[0,q.h,1,-1],[q.w,q.h,-1,-1]]){ctx.beginPath();ctx.moveTo(x,y+sy*3);ctx.lineTo(x,y);ctx.lineTo(x+sx*3,y);ctx.stroke()}ctx.restore();
}
function drawEncounterBodyFX(){
 const b=L.boss;if(!b)return;
 const core=bossCore(b),cx=core.x+core.w/2,cy=core.y+core.h/2;
 if(b.phase==='recover'&&!b.dead){const frame=experience.reduced?1:Math.floor(clock*5)%3;encounterBlit(L.world,'recover',frame,cx-36,cy-36,72,72)}
 if(!experience.reduced&&b.phase==='attack'&&[1,3].includes(b.style))encounterBlit(L.world,'attack',encounterPhaseFrame(b),b.x-22,b.y+20,72,58,b.direction<0);
 if(Number.isFinite(b.hitAt)&&clock-b.hitAt<.24)encounterBlit(L.world,'attack',Math.min(3,Math.floor((clock-b.hitAt)/.06)),cx-36,cy-36,72,72);
}
const narrative={active:false,scene:null,page:0,time:0,mode:'live',callback:null,seen:new Set(),unlocked:new Set(),repaired:false,restoreFocus:null};
try{const saved=JSON.parse(localStorage.getItem('nr-story-v08')||'[]');if(Array.isArray(saved))for(const id of saved)if(STORY_SCENES[id])narrative.unlocked.add(id)}catch{}

function storyScrollLock(on){
 if(!document.body)return;
 if(on){if(!narrative.scrollLocked)narrative.previousOverflow=document.body.style.overflow;narrative.scrollLocked=true;document.body.style.overflow='hidden'}
 else if(narrative.scrollLocked){document.body.style.overflow=narrative.previousOverflow||'';narrative.scrollLocked=false}
}

function rememberStory(id){narrative.unlocked.add(id);try{localStorage.setItem('nr-story-v08',JSON.stringify([...narrative.unlocked]))}catch{}}
function cancelStory(){narrative.active=false;narrative.callback=null;narrative.scene=null;$('#storyOverlay').hidden=true;storyScrollLock(false);clear()}
function openStory(id,mode='live',callback=null){
 if(!STORY_SCENES[id])return false;
 narrative.restoreFocus=document.activeElement?.closest?.('#storyOverlay')?$('#journal'):document.activeElement;narrative.active=true;narrative.scene=id;narrative.mode=mode;narrative.page=0;narrative.time=0;narrative.callback=mode==='live'?callback:null;
 if(mode==='live')rememberStory(id);storyScrollLock(true);clear();$('#storyOverlay').hidden=false;$('#storyPages').hidden=false;$('#journalList').hidden=true;$('#storyStage').hidden=false;renderStoryText();$('#storyNext').focus?.();return true;
}
function closeStory(){
 const callback=narrative.callback,focus=narrative.restoreFocus;
 narrative.callback=null;narrative.active=false;narrative.scene=null;$('#storyOverlay').hidden=true;storyScrollLock(false);clear();acc=0;
 if(callback)callback();focus?.focus?.();
}
function storyNext(){if(!narrative.active)return;if(narrative.mode==='journal'){closeStory();return}const scene=STORY_SCENES[narrative.scene];if(narrative.page+1<scene.pages.length){narrative.page++;narrative.time=0;renderStoryText()}else closeStory()}
function renderStoryText(){
 const scene=STORY_SCENES[narrative.scene],page=scene.pages[narrative.page];
 $('#storyTitle').textContent=scene.title;$('#storySpeaker').textContent=page.speaker;
 $('#storyProgress').textContent='TRANG '+(comicScenePage()+1)+' / '+Math.ceil(scene.pages.length/3)+' · LỜI '+(narrative.page+1)+'/'+scene.pages.length+(narrative.mode==='replay'?' · XEM LẠI':'');
 resetComicBeat();
}
function openJournal(){
 narrative.restoreFocus=document.activeElement||$('#journal');storyScrollLock(true);clear();narrative.active=true;narrative.mode='journal';narrative.scene=null;narrative.callback=null;
 $('#storyOverlay').hidden=false;$('#storyTitle').textContent='Nhật ký Luma';$('#storyPages').hidden=true;$('#storyStage').hidden=true;$('#journalList').hidden=false;$('#comicStrip').hidden=true;$('#journalList').replaceChildren();
 for(const [id,scene] of Object.entries(STORY_SCENES)){
  const button=document.createElement('button');button.textContent=(narrative.unlocked.has(id)?'✓ ':'◌ ')+scene.title;button.onclick=()=>openStory(id,'replay');$('#journalList').append(button);
 }
 $('#storyProgress').textContent=narrative.unlocked.size+' cảnh đã mở · Bản thử cho phép xem lại mọi cảnh';$('#storyNext').textContent='Đóng nhật ký';$('#storyNext').focus?.();
}
function onNarrativeLevelLoaded(){
 if(globalThis.__NEON_QA_NO_AUTOSTORY__||globalThis.neonBooting)return;
 if(idx%8===0){const id='arrival'+L.world;if(!narrative.seen.has(id)){narrative.seen.add(id);openStory(id)}}
}
function beforeBossFinish(){
 const b=L.boss;if(!b||!b.dead||b.storyDone)return false;
 if(globalThis.__NEON_QA_NO_AUTOSTORY__){b.storyDone=true;if(L.world===5)narrative.repaired=true;return false}
 if(!b.storyStarted){
  b.storyStarted=true;openStory('boss'+L.world,'live',()=>{b.storyDone=true;if(L.world===5)narrative.repaired=true;finish()});
 }
 return true;
}
function checkRescueStory(){
 if(globalThis.__NEON_QA_NO_AUTOSTORY__||narrative.active)return;
 const id=idx===0?'pip-rescue':idx===2?'engineer-rescue':null;
 if(id&&objective()&&!narrative.seen.has(id)){narrative.seen.add(id);openStory(id)}
}
function tickStory(dt){narrative.time+=dt;if(narrative.scene){comic.revealed=Math.min(comicBeatText().length,comic.revealed+dt*38);comic.full=comic.revealed>=comicBeatText().length;updateComicText()}}
