 $('#journal').onclick=openJournal;$('#levelsMenu').onclick=()=>{const panel=$('#reviewTools');panel.open=!panel.open;clear();if(panel.open&&!won&&!narrative.active)pause(true)};$('#quickFull').onclick=()=>$('#full').onclick();$('#storyNext').onclick=advanceStory;$('#storySkip').onclick=closeStory;
 $('#lowFx').onclick=()=>{experience.reduced=!experience.reduced;$('#lowFx').textContent=experience.reduced?'FX: nhẹ':'FX: đủ'};
