for(const name of ['left','right','jump']){const el=$('#'+name);el.addEventListener('pointerdown',e=>{e.preventDefault();if(globalThis.neonMenuOpen||narrative.active||paused||won||art.dying>0)return;el.setPointerCapture(e.pointerId);touch[name].add(e.pointerId);sync()});for(const t of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(t,e=>{touch[name].delete(e.pointerId);sync()});el.oncontextmenu=e=>e.preventDefault()}
addEventListener('keydown',e=>{if(globalThis.neonMenuOpen&&!narrative.active){menuKey(e);return;}if(!$('#pauseOverlay').hidden&&!narrative.active){if(['Escape','KeyP'].includes(e.code)){e.preventDefault();closePauseMenu()}return;}if(narrative.active){if(['Enter','Space','Escape'].includes(e.code)){e.preventDefault();if(!e.repeat){if(e.code==='Escape')closeStory();else advanceStory()}}return}if(['ArrowLeft','ArrowRight','ArrowUp','Space','KeyA','KeyD'].includes(e.code)){e.preventDefault();keys.add(e.code);sync()}if(e.repeat)return;if(e.code==='KeyJ'){e.preventDefault();attackBoss()}if(e.code==='KeyE')interact();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(['KeyP','Escape'].includes(e.code)){if(!$('#pauseOverlay').hidden)closePauseMenu();else showPauseMenu()}if(e.code==='KeyR')load(idx)});addEventListener('keyup',e=>{keys.delete(e.code);sync()});addEventListener('blur',()=>pause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true)});$('#attack').onclick=attackBoss;$('#act').onclick=interact;$('#dash').onclick=dash;$('#pause').onclick=()=>pause(!paused);$('#restart').onclick=()=>load(idx);$('#tryBoss').onclick=()=>load(7);$('#load').onclick=()=>load(Number($('#select').value));$('#next').onclick=()=>load(Math.min(39,idx+1));$('#debug').onclick=()=>{$('#debug').textContent='Collider/sơ đồ: '+((showMap=!showMap)?'bật':'tắt')};
